const response = await window.fs.readFile('export.csv', { encoding: 'utf8' });
import Papa from 'papaparse';
import _ from 'lodash';

const parseResult = Papa.parse(response, {
  header: true,
  skipEmptyLines: true,
  dynamicTyping: true
});

const data = parseResult.data;

// Extract domain information from URLs to help with categorization
function extractDomain(url) {
  try {
    if (!url) return null;
    const domain = new URL(url).hostname;
    return domain
      .replace('www.', '')
      .split('.')
      .slice(0, -1)
      .join('.');
  } catch (e) {
    return null;
  }
}

// Add domain information to each entry
data.forEach(item => {
  item.domain = extractDomain(item.url);
});

// Count domains to identify common sources
const domainCounts = _.countBy(data, 'domain');
const topDomains = Object.entries(domainCounts)
  .filter(([domain]) => domain) // Remove null domains
  .sort((a, b) => b[1] - a[1])
  .slice(0, 15);

console.log("Top 15 domains:", topDomains);

// Extract keywords from titles and excerpts for topic modeling
function extractKeywords(text) {
  if (!text) return [];

  // Remove common words and symbols
  const stopWords = new Set(['a', 'an', 'the', 'and', 'or', 'but', 'is', 'in', 'on', 'at', 'to', 'for', 'with', 'by', 'about', 'like', 'through', 'over', 'before', 'between', 'after', 'since', 'without', 'under', 'of', 'from', 'this', 'that', 'these', 'those', 'it', 'its']);

  return text.toLowerCase()
    .replace(/[^\w\s]/g, ' ') // Remove punctuation
    .split(/\s+/)
    .filter(word => word.length > 2 && !stopWords.has(word));
}

// Extract potential topics by analyzing words in titles
const allKeywords = [];
data.forEach(item => {
  const titleKeywords = item.title ? extractKeywords(item.title) : [];
  const excerptKeywords = item.excerpt ? extractKeywords(item.excerpt) : [];
  const keywords = [...titleKeywords, ...excerptKeywords];

  if (keywords.length > 0) {
    allKeywords.push(...keywords);
  }
});

// Count keyword frequency
const keywordCounts = _.countBy(allKeywords);
const topKeywords = Object.entries(keywordCounts)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 50);

console.log("Top 50 keywords:", topKeywords);

// Look for patterns in YouTube content
const youtubeVideos = data.filter(item => item.domain === 'youtube');
console.log(`YouTube videos: ${youtubeVideos.length}`);

// Extract YouTube topics from titles
const youtubeTopics = [];
youtubeVideos.forEach(video => {
  if (video.title) {
    // Look for text in parentheses, hashtags, or other patterns
    const hashtagMatch = video.title.match(/#(\w+)/g);
    if (hashtagMatch) {
      youtubeTopics.push(...hashtagMatch.map(tag => tag.substring(1)));
    }

    // Extract words from titles
    youtubeTopics.push(...extractKeywords(video.title));
  }
});

const youtubeTopicCounts = _.countBy(youtubeTopics);
const topYoutubeTopics = Object.entries(youtubeTopicCounts)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 20);

console.log("Top YouTube topics:", topYoutubeTopics);

