  // Assign the highest scoring topic as the primary topic
  const scores = Object.entries(item.topicScores);
  if (scores.length > 0) {
    scores.sort((a, b) => b[1] - a[1]);
    item.primaryTopic = scores[0][1] > 0 ? scores[0][0] : "Uncategorized";
