// Function to categorize a bookmark
function categorizeBookmark(bookmark) {
  const text = `${bookmark.title || ''} ${bookmark.excerpt || ''} ${bookmark.domain || ''}`.toLowerCase();

  // Check YouTube special case
  if (bookmark.domain === 'youtube') {
    // Check for yoga content
    if (/yoga|stretch|flow|vinyasa|hatha/i.test(text)) {
      return {
        mainCategory: "Health & Wellness",
        subCategory: "Yoga",
        specificTopic: determineYogaStyle(text)
      };
    }

    // Check for finance content
    if (/trading|market|invest|finance|stock|money/i.test(text)) {
      return {
        mainCategory: "Finance & Investing",
        subCategory: "Investment Education",
        specificTopic: "Video Tutorials"
      };
    }

    // Default YouTube to Entertainment
    return {
      mainCategory: "Entertainment & Media",
      subCategory: "Videos",
      specificTopic: determineVideoType(text)
    };
  }

  // Check for banking sites
  if (/bank|cibc|rbc|bmo|scotia|td/i.test(bookmark.domain || '')) {
    return {
      mainCategory: "Productivity & Tools",
      subCategory: "Financial Tools",
      specificTopic: "Banking"
    };
  }

  // Try to match against our category structure
  for (const [mainCategory, subCategories] of Object.entries(categoryStructure)) {
    for (const [subCategory, keywords] of Object.entries(subCategories)) {
      for (const keyword of keywords) {
        if (text.includes(keyword)) {
          return {
            mainCategory,
            subCategory,
            specificTopic: determineSpecificTopic(mainCategory, subCategory, text)
          };
        }
      }
    }
  }

  // If nothing matches, try domain-based categorization
  return domainBasedCategorization(bookmark);
}

// Helper function to determine yoga style
function determineYogaStyle(text) {
  if (/vinyasa/i.test(text)) return "Vinyasa";
  if (/hatha/i.test(text)) return "Hatha";
  if (/power/i.test(text)) return "Power Yoga";
  if (/flow/i.test(text)) return "Flow Yoga";
  if (/stretch/i.test(text)) return "Stretching";
  return "General Yoga";
}

// Helper function to determine video type
function determineVideoType(text) {
  if (/tutorial|how to|learn|guide/i.test(text)) return "Tutorials";
  if (/motivation|inspire|speech/i.test(text)) return "Motivational";
  if (/review|analysis/i.test(text)) return "Reviews";
  if (/news|update|latest/i.test(text)) return "News";
  return "General Videos";
}

// Helper function to determine specific topic
function determineSpecificTopic(mainCategory, subCategory, text) {
  // Finance specific topics
  if (mainCategory === "Finance & Investing") {
    if (/futures/i.test(text)) return "Futures Trading";
    if (/stock/i.test(text)) return "Stock Market";
    if (/forex/i.test(text)) return "Forex";
    if (/options/i.test(text)) return "Options Trading";
    if (/crypto/i.test(text)) return "Cryptocurrency";
    if (/invest/i.test(text)) return "Investments";
    return "General Finance";
  }

  // Technology specific topics
  if (mainCategory === "Technology & Development") {
    if (/windows/i.test(text)) return "Windows";
    if (/microsoft/i.test(text)) return "Microsoft";
    if (/python/i.test(text)) return "Python";
    if (/javascript/i.test(text)) return "JavaScript";
    if (/ai|artificial intelligence/i.test(text)) return "AI Tools";
    return "General Tech";
  }

  // Default to a generic topic
  return "General";
}

// Domain-based categorization for hard-to-classify bookmarks
function domainBasedCategorization(bookmark) {
  const domain = bookmark.domain || '';

  if (/google|microsoft|apple|amazon/i.test(domain)) {
    return {
      mainCategory: "Technology & Development",
      subCategory: "Software & Tools",
      specificTopic: domain.charAt(0).toUpperCase() + domain.slice(1)
