// Generate tags for each bookmark
function generateTags(bookmark) {
  const tags = [];

  // Content type tags
  if (bookmark.domain === 'youtube') tags.push('#video');
  else if (/\.pdf$/i.test(bookmark.url || '')) tags.push('#pdf');
  else if (/tool|app|software/i.test(bookmark.title || '')) tags.push('#tool');
  else if (/article|blog|post/i.test(bookmark.title || '')) tags.push('#article');
  else if (/tutorial|course|class|lesson/i.test(bookmark.title || '')) tags.push('#tutorial');

  // Purpose tags
  if (/learn|tutorial|course|education/i.test(bookmark.mainCategory + bookmark.subCategory)) {
    tags.push('#learn');
  } else if (/reference|research|data/i.test(bookmark.mainCategory + bookmark.subCategory)) {
    tags.push('#reference');
  }

  // Special interest tags
  if (/trading|market|invest/i.test(bookmark.title || '')) tags.push('#finance');
  if (/yoga|fitness|exercise/i.test(bookmark.title || '')) tags.push('#fitness');
  if (/canada|canadian/i.test(bookmark.title || '')) tags.push('#canada');

  return tags.join(', ');
}

